window.kbPageData["views/entry/k-31f2a5d877f77b62"] = {"key":"entry/k-31f2a5d877f77b62","state":{"route":"entry/k-31f2a5d877f77b62"},"node":{"id":"k-31f2a5d877f77b62","mode":"k","title":"文献流通率与文献利用率","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":["文献流通率与文献利用率的分母口径"],"qs":["国考 2024 地市级 行测#90"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"文献流通率是文献流通数占馆藏中提供流通的文献数的比率。文献利用率是文献流通数占馆藏文献总数的比率。","review":{"definition":"文献流通率是文献流通数占馆藏中提供流通的文献数的比率。文献利用率是文献流通数占馆藏文献总数的比率。","explanation":"同一图书馆的两项指标都以实际被借阅、利用的文献数为分子。提供流通的文献数至多等于馆藏文献总数，因此在两率均可计算时，文献流通率至少等于文献利用率，A项正确。D项只给出了流通数与提供流通的文献数的变化，缺少馆藏文献总数的变化，无法判断利用率是否上升。","references":[],"evidence":"文献流通率的分母一定小于或等于文献利用率的分母","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#90":{"paper":"国考 2024 地市级 行测","n":90,"mod":"判断推理","src":["92d0b72e86a6a33d568d.pdf",19],"asrc":["e1792c53900a45f1b9fa.pdf",30],"card":"96cd9f781054c6bcaf34ce87","links":[{"id":"k-31f2a5d877f77b62","role":"直接考查","why":"两率均以文献流通数为分子，分母分别为馆藏中提供流通的文献数和馆藏文献总数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-31f2a5d877f77b62":[["国考 2024 地市级 行测#90"]]}};
